import Foundation
import UIKit

// Small row icon for the "WewPagram" entry in Settings, embedded as base64
// so we don't need to touch the Bazel asset-catalog build targets.
public enum WewPagramIcon {
    private static let base64 = ""

    public static let rowIcon: UIImage? = {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return UIImage(data: data, scale: 2.0)?.withRenderingMode(.alwaysOriginal)
    }()
}
